/// @brief Enumeration for the neural network layer type of NNTrainer.
/// @since_tizen 6.0
abstract class ml_train_layer_type_e {
  /// < Input Layer
  static const int ML_TRAIN_LAYER_TYPE_INPUT = 0;

  /// < Fully Connected Layer
  static const int ML_TRAIN_LAYER_TYPE_FC = 1;

  /// < Batch Normalization Layer (Since 6.5)
  static const int ML_TRAIN_LAYER_TYPE_BN = 2;

  /// < Convolution 2D Layer (Since 6.5)
  static const int ML_TRAIN_LAYER_TYPE_CONV2D = 3;

  /// < Pooling 2D Layer (Since 6.5)
  static const int ML_TRAIN_LAYER_TYPE_POOLING2D = 4;

  /// < Flatten Layer (Since 6.5)
  static const int ML_TRAIN_LAYER_TYPE_FLATTEN = 5;

  /// < Activation Layer (Since 6.5)
  static const int ML_TRAIN_LAYER_TYPE_ACTIVATION = 6;

  /// < Addition Layer (Since 6.5)
  static const int ML_TRAIN_LAYER_TYPE_ADDITION = 7;

  /// < Concat Layer (Since 6.5)
  static const int ML_TRAIN_LAYER_TYPE_CONCAT = 8;

  /// < MultiOut Layer (Since 6.5)
  static const int ML_TRAIN_LAYER_TYPE_MULTIOUT = 9;

  /// < Embedding Layer (Since 6.5)
  static const int ML_TRAIN_LAYER_TYPE_EMBEDDING = 10;

  /// < RNN Layer (Since 6.5)
  static const int ML_TRAIN_LAYER_TYPE_RNN = 11;

  /// < LSTM Layer (Since 6.5)
  static const int ML_TRAIN_LAYER_TYPE_LSTM = 12;

  /// < Split Layer (Since 6.5)
  static const int ML_TRAIN_LAYER_TYPE_SPLIT = 13;

  /// < GRU Layer (Since 6.5)
  static const int ML_TRAIN_LAYER_TYPE_GRU = 14;

  /// < Permute layer (Since 6.5)
